+            seq_lens.data_ptr<int64_t>(),
+            buffer.data_ptr<scalar_t>(),
+            sinks_tensor.data_ptr<scalar_t>(),
+            num_seqs,
+            num_heads,
+            head_size,
+            head_size_v,
+            num_kv_splits,
+            q_strideM,
+            q_strideH,
+            k_strideN,
+            k_strideH,
+            v_strideN,
+            v_strideH,
+            sm_scale,
+            logit_cap,
+            max_num_reqs,
+            max_context_len,
+            max_total_num_tokens,
+            size_per_thread,
+            has_sink);
+      } else {
+        // GQA/MQA
+        decode_attention_grouped_kernel_impl<scalar_t, index_t, BLOCK_N>(
+            output.data_ptr<scalar_t>(),
+            attn_logits.data_ptr<float>(),
+            query.data_ptr<scalar_t>(),
+            (const scalar_t*)k_buffer_data,
+            (const scalar_t*)v_buffer_data,
+            req_to_token.data_ptr<index_t>(),
+            req_pool_indices.data_ptr<int64_t>(),
+            seq_lens.data_ptr<int64_t>(),
+            encoder_lens_t.data_ptr<int64_t>(),
+            sinks_tensor.data_ptr<scalar_t>(),
+            num_seqs,
+            num_heads,
+            num_heads_kv,
+            head_size,
+            head_size_v,
+            num_kv_splits,
+            q_strideM,
+            q_strideH,
+            k_strideN,
