+    s_prime[row] *= m_delta;
+    s_prime[row] += at::vec::reduce_all<float>([](Vec& x, Vec& y) { return x + y; }, s_delta + row * BLOCK_N, n_size);
+
+    m_prime[row] = m_i;
+
+    // v' <- v' * m_delta
+    at::vec::map<float>(
+        [m_delta](Vec x) { return x * Vec(m_delta); },
+        v_prime + row * head_size_v,
+        v_prime + row * head_size_v,
+        head_size_v);
