+    // convert the columns that brgemm will consume.
+    fill_stub(s_delta + row * BLOCK_N + n_size, 0.f, padded_n_size - n_size);
+    copy_stub<scalar_t>(s_delta2 + row * BLOCK_N, s_delta + row * BLOCK_N, 1.f, padded_n_size);
+  }
