+      va = _mm512_mul_ps(_mm512_loadu_ps(s_i + m * BLOCK_N + n), vscale);
+      va = _mm512_fexp_u20_ps(_mm512_sub_ps(va, vmax));
+      vsum = _mm512_add_ps(vsum, va);
